# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUR\'AN KAVRAMLARINI ÖĞRENİYORUM: VELÎ VE EVLİYÂ (1.8)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Velî Kavramının Anlam Çerçevesi</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Sözlük Anlamı:</tspan> Dost, yardımcı, koruyan,</text>\n  <text x="42" y="107" font-size="10.5" fill="#1e3a8a">gözeten, sahip çıkan ve yakın olan (çoğulu: <tspan font-weight="bold">Evliyâ</tspan>).</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">el-Velî (Esma-i Hüsna):</tspan> Mümin kullarını seven,</text>\n  <text x="42" y="143" font-size="10.5" fill="#1e3a8a">onlara yardım eden ve işlerini üstlenen Yüce Allah.</text>\n  <rect x="32" y="158" width="296" height="68" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="176" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Bakara Suresi 257. Ayet:</text>\n  <text x="180" y="193" text-anchor="middle" font-size="10" fill="#1e3a8a">"Allah iman edenlerin velîsidir (dostu ve yardımcısıdır);</text>\n  <text x="180" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">onları karanlıklardan aydınlığa (nura) çıkarır..."</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Allah\'ın Dostları (Evliyâullah) ve Müminler</text>\n  <rect x="372" y="82" width="296" height="68" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="100" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Yûnus Suresi 62–63. Ayetler:</text>\n  <text x="520" y="117" text-anchor="middle" font-size="10" fill="#14532d">"Bilesiniz ki Allah\'ın dostlarına (evliyâsına) korku yoktur,</text>\n  <text x="520" y="132" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">onlar üzülmeyeceklerdir de. Onlar iman edip takvaya erenlerdir."</text>\n  <rect x="372" y="158" width="296" height="68" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="176" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Tevbe Suresi 71. Ayet (Mümin Kardeşliği):</text>\n  <text x="520" y="193" text-anchor="middle" font-size="10" fill="#14532d">"Mümin erkekler ve mümin kadınlar birbirlerinin velîleridir;</text>\n  <text x="520" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">iyiliği emreder, kötülükten alıkoyarlar..."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUR\'AN\'DA BİRBİRİNİN ZIDDI İKİ TEMEL KAVRAM: ADALET VE ZULÜM</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ADALET (Hakkı Yerine Koymak)</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Anlamı:</tspan> Doğruluk, denge, eşitlik ve her</text>\n  <text x="42" y="107" font-size="10.5" fill="#1e3a8a">şeyi kendisine layık olan yere koymak.</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">el-Adl:</tspan> Mutlak adil olan Yüce Allah.</text>\n  <text x="32" y="148" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kıst:</tspan> Ölçü ve tartıda, şahitlikte hakkaniyet.</text>\n  <rect x="32" y="162" width="296" height="64" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="180" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Nahl Suresi 90. Ayet:</text>\n  <text x="180" y="196" text-anchor="middle" font-size="10" fill="#1e3a8a">"Şüphesiz Allah, adaleti, ihsanı (iyiliği) ve yakınlara</text>\n  <text x="180" y="211" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">yardım etmeyi emreder; hayasızlığı ve zulmü yasaklar..."</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">ZULÜM (Haddi Aşmak ve Haksızlık)</text>\n  <text x="372" y="92" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Anlamı:</tspan> Bir şeyi yerli yerine koymamak,</text>\n  <text x="382" y="107" font-size="10.5" fill="#7f1d1d">haksızlık etmek, sınırı aşmak (adaletin zıddı).</text>\n  <text x="372" y="128" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">1. Allah\'a Karşı Zulüm:</tspan> En büyük zulüm <tspan font-weight="bold">ŞİRK</tspan>\'tir</text>\n  <text x="382" y="143" font-size="10.5" fill="#7f1d1d">(Lokmân, 31/13: "Şirk gerçekten büyük bir zulümdür").</text>\n  <text x="372" y="163" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">2. İnsanlara Zulüm:</tspan> Kul hakkı, baskı ve haksızlık.</text>\n  <text x="372" y="183" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">3. Nefse Zulüm:</tspan> Günah işleyerek kendi ahiretini</text>\n  <text x="382" y="198" font-size="10.5" fill="#7f1d1d">tehlikeye atmak (<tspan font-weight="bold">zulmü\'n-nefs</tspan>).</text>\n  <text x="520" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">"Allah kullarına zerre kadar zulmetmez!" (Fussilet 46)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUR\'AN-I KERİM\'DE ŞEFAAT KAVRAMI VE ŞARTLARI</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Şefaat Kavramının Tanımı</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Sözlükte:</tspan> Tek olanı çift yapmak, birinin</text>\n  <text x="42" y="107" font-size="10.5" fill="#78350f">yardımına koşup onun adına aracılık etmek.</text>\n  <text x="32" y="128" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Dini Terim Olarak:</tspan> Ahiret gününde günahkâr</text>\n  <text x="42" y="143" font-size="10.5" fill="#78350f">müminlerin bağışlanması veya derecelerinin</text>\n  <text x="42" y="158" font-size="10.5" fill="#78350f">yükselmesi için Allah\'ın izin verdiği zatların</text>\n  <text x="42" y="173" font-size="10.5" font-weight="bold" fill="#b45309">Allah\'a dua ve niyazda bulunmasıdır.</text>\n  <rect x="32" y="186" width="296" height="40" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="180" y="203" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">Zümer 44: "De ki: Şefaatin tamamı Allah\'a aittir!"</text>\n  <text x="180" y="218" text-anchor="middle" font-size="10" fill="#78350f">(Putların ve sahte aracıların şefaati reddedilmiştir)</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Kur\'an\'a Göre Şefaatin İki Temel Şartı</text>\n  <rect x="374" y="84" width="292" height="65" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="520" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">1. Allah\'ın Şefaat Edene İzin Vermesi:</text>\n  <text x="520" y="119" text-anchor="middle" font-size="10" fill="#581c87">"O\'nun izni olmadan katında kim şefaat edebilir?"</text>\n  <text x="520" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">(Bakara Suresi, 255 - Âyetü\'l-Kürsî)</text>\n  <rect x="374" y="158" width="292" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="520" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">2. Şefaat Edilecek Kişiden Allah\'ın Razı Olması:</text>\n  <text x="520" y="193" text-anchor="middle" font-size="10" fill="#581c87">"Allah\'ın razı olduğu kimselerden başkasına şefaat</text>\n  <text x="520" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">edemezler (tevhid ehli mümin olmalı)." (Enbiyâ, 28)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
